// Author: MiYu. Original LightningData and actual lightning handles supply script geometry, colors and lifetime.
#include "session.h"
#include <bit>
#include <cmath>
#include <algorithm>

namespace war3 {
namespace {
float number(jass::Real v){return std::bit_cast<float>(v.bits());}
jass::Real real(float v){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(v));}
void coordinates(const std::array<jass::Real,3>& p){for(auto value:p)if(!std::isfinite(number(value)) || std::abs(number(value))>1000000000)throw std::runtime_error("Lightning coordinate exceeds supported range");}
}
const LightningInfo& ScriptSession::lightningInfo(const std::string& type) {
    if(lightningInfo_.empty()){auto table=SourceTable::read(requireWorld().resources(),"Splats\\LightningData.slk");for(auto& row:table.rows()){auto text=[&](const char* key){auto found=row.find(key);if(found==row.end() || found->second.empty() || found->second=="_")throw std::runtime_error("Missing lightning field: "+std::string(key));return found->second;};auto field=[&](const char* key){auto value=text(key);size_t end=0;float v=std::stof(value,&end);if(end!=value.size() || !std::isfinite(v))throw std::runtime_error("Invalid lightning field: "+std::string(key));return v;};LightningInfo info;info.type=text("Name");info.texture=text("Dir")+"\\"+text("file");info.segment=field("AvgSegLen");info.width=field("Width");info.noise=field("NoiseScale");info.texCoordScale=field("TexCoordScale");info.duration=field("Duration");unsigned i=0;for(auto key:{"R","G","B","A"}){auto value=field(key);if(value<0 || value>255)throw std::runtime_error("Lightning source color out of range");info.color[i++]=value/255;}if(info.type.size()!=4 || info.segment<=0 || info.segment>100000 || std::abs(info.texCoordScale)>1000000 || info.width<0 || info.width>100000 || info.noise<0 || info.noise>100000 || info.duration<0 || info.duration>86400 || lightningInfo_.size()>=1024 || !lightningInfo_.emplace(info.type,std::move(info)).second)throw std::runtime_error("Invalid source lightning definition");}}
    auto found=lightningInfo_.find(type);if(found==lightningInfo_.end())throw std::runtime_error("Unknown source lightning: "+type);return found->second;
}
jass::Value ScriptSession::createLightning(const std::string& type,bool visibility,std::array<jass::Real,3> from,std::array<jass::Real,3> to,std::optional<double> duration) {
    coordinates(from);coordinates(to);if(lightnings_.size()>=8192)throw std::runtime_error("Lightning instance budget exceeded");auto source=lightningInfo(type);auto h=create(NativeKind::Lightning);auto state=std::make_shared<ScriptLightning>();state->id=h.bits;state->source=std::move(source);state->color=state->source.color;state->from=from;state->to=to;state->checkVisibility=visibility;state->born=simulationTime_;if(duration){if(!std::isfinite(*duration) || *duration<0 || *duration>86400)throw std::runtime_error("Lightning duration exceeds bounds");state->expires=simulationTime_+*duration;}std::get<std::shared_ptr<ScriptLightning>>(object(h,NativeKind::Lightning).state)=state;lightnings_[h.bits]=std::move(state);return h;
}
bool ScriptSession::destroyLightning(std::uint32_t id) {if(!alive(id,NativeKind::Lightning))return false;lightnings_.erase(id);destroy(runtime_.handle("lightning",id),NativeKind::Lightning);return true;}
bool ScriptSession::moveLightning(std::uint32_t id,bool visibility,std::array<jass::Real,3> from,std::array<jass::Real,3> to) {if(!alive(id,NativeKind::Lightning))return false;coordinates(from);coordinates(to);auto state=lightnings_.at(id);state->from=from;state->to=to;state->checkVisibility=visibility;state->fromUnit=state->toUnit=0;return true;}
void ScriptSession::lightningTick() {
    std::vector<std::uint32_t> expired;for(auto& [id,l]:lightnings_){if(l->expires && *l->expires<=simulationTime_){expired.push_back(id);continue;}auto follow=[&](std::uint32_t unit,std::array<jass::Real,3>& point,float offset){if(!unit)return;if(!alive(unit,NativeKind::Unit)){expired.push_back(id);return;}auto u=units_.at(unit);point={u->x,u->y,real(requireWorld().height({u->x,u->y})+u->flyHeight+offset)};};follow(l->fromUnit,l->from,l->fromHeight);follow(l->toUnit,l->to,l->toHeight);}for(auto id:expired)destroyLightning(id);
}
void ScriptSession::spellLightning(const SpellMissile& missile) {
    auto effects=definitions().field(missile.spell.ability,"Profile","LightningEffect");if(effects.empty() || effects=="_")return;auto comma=effects.find(',');auto code=missile.visited.empty() || comma==std::string::npos?effects.substr(0,comma):effects.substr(comma+1);if(auto end=code.find(',');end!=std::string::npos)code.resize(end);auto first=code.find_first_not_of(" \t\"");if(first==std::string::npos)return;code=code.substr(first,code.find_last_not_of(" \t\"")-first+1);if(code.empty() || code=="_")return;auto source=missile.visited.empty()?missile.source:missile.visited.back();if(!alive(source,NativeKind::Unit) || !alive(missile.target,NativeKind::Unit))return;auto from=units_.at(source),to=units_.at(missile.target);auto h=createLightning(code,true,{from->x,from->y,real(requireWorld().height({from->x,from->y})+from->flyHeight+definitions().number(from->type,"UnitWeapons","launchZ"))},{to->x,to->y,real(requireWorld().height({to->x,to->y})+to->flyHeight+definitions().number(to->type,"UnitWeapons","impactZ",60))},lightningInfo(code).duration);auto l=lightnings_.at(h.bits);l->fromUnit=source;l->toUnit=missile.target;l->fromHeight=definitions().number(from->type,"UnitWeapons","launchZ");l->toHeight=definitions().number(to->type,"UnitWeapons","impactZ",60);
}
void ScriptSession::bindLightningNatives() {
    auto text=[](const jass::Value& v){return v.text?*v.text:std::string{};};auto point=[](auto a,size_t at){return std::array{jass::Real::fromBits(a[at].bits),jass::Real::fromBits(a[at+1].bits),jass::Real::fromBits(a[at+2].bits)};};
    bind("AddLightning","lightning",{"string","boolean","real","real","real","real"},[this,text](auto&,auto a){WorldPoint from{jass::Real::fromBits(a[2].bits),jass::Real::fromBits(a[3].bits)},to{jass::Real::fromBits(a[4].bits),jass::Real::fromBits(a[5].bits)};return createLightning(text(a[0]),a[1].bits!=0,{from.x,from.y,real(requireWorld().height(from))},{to.x,to.y,real(requireWorld().height(to))});});
    bind("AddLightningEx","lightning",{"string","boolean","real","real","real","real","real","real"},[this,text,point](auto&,auto a){return createLightning(text(a[0]),a[1].bits!=0,point(a,2),point(a,5));});
    bind("DestroyLightning","boolean",{"lightning"},[this](auto& vm,auto a){return vm.boolean(destroyLightning(a[0].bits));});
    bind("MoveLightning","boolean",{"lightning","boolean","real","real","real","real"},[this](auto& vm,auto a){WorldPoint from{jass::Real::fromBits(a[2].bits),jass::Real::fromBits(a[3].bits)},to{jass::Real::fromBits(a[4].bits),jass::Real::fromBits(a[5].bits)};return vm.boolean(moveLightning(a[0].bits,a[1].bits!=0,{from.x,from.y,real(requireWorld().height(from))},{to.x,to.y,real(requireWorld().height(to))}));});
    bind("MoveLightningEx","boolean",{"lightning","boolean","real","real","real","real","real","real"},[this,point](auto& vm,auto a){return vm.boolean(moveLightning(a[0].bits,a[1].bits!=0,point(a,2),point(a,5)));});
    for(auto [name,index]:{std::pair{"GetLightningColorR",0u},{"GetLightningColorG",1u},{"GetLightningColorB",2u},{"GetLightningColorA",3u}})bind(name,"real",{"lightning"},[this,index](auto& vm,auto a){return vm.real(real(std::get<std::shared_ptr<ScriptLightning>>(object(a[0],NativeKind::Lightning).state)->color[index]));});
    bind("SetLightningColor","boolean",{"lightning","real","real","real","real"},[this](auto& vm,auto a){if(!alive(a[0].bits,NativeKind::Lightning))return vm.boolean(false);auto l=lightnings_.at(a[0].bits);for(unsigned i=0;i<4;++i){float value=number(jass::Real::fromBits(a[i+1].bits));if(!std::isfinite(value))throw std::runtime_error("Non-finite lightning color");l->color[i]=std::clamp(value,0.f,1.f);}return vm.boolean(true);});
}
}
